from collections import defaultdict

class Solution:
    def diagonalSort(self, mat: list[list[int]]) -> list[list[int]]:
        m, n = len(mat), len(mat[0])
        diags = defaultdict(list)
        for i in range(m):
            for j in range(n):
                diags[i - j].append(mat[i][j])
        for key in diags:
            diags[key].sort()
        idx = defaultdict(int)
        for i in range(m):
            for j in range(n):
                mat[i][j] = diags[i - j][idx[i - j]]
                idx[i - j] += 1
        return mat

